type AlertItem = { id: number; title: string; camera: string; location: string; time: string; level: "高" | "中" | "低"; type: string; status: "待处理" | "已确认" };
type RoleKey = "super_admin" | "security_lead" | "guard" | "counselor" | "supervisor" | "employee" | "auditor";
type Role = { key: RoleKey; name: string; desc: string; scope: string; permissions: string[] };

const roles: Role[] = [
  { key: "super_admin", name: "超级管理员", desc: "平台运维，拥有全部权限", scope: "园区全量", permissions: ["user:view", "role:view", "behavior:view", "trajectory:view", "report:view", "audit:view", "consent:view"] },
  { key: "security_lead", name: "园区安全负责人", desc: "安保/EHS 主管，负责异常行为与轨迹监测", scope: "园区全量", permissions: ["user:view", "role:view", "behavior:view", "trajectory:view", "report:view", "audit:view", "consent:view"] },
  { key: "guard", name: "安保/巡检人员", desc: "一线安保、巡检员，按辖区查看监测", scope: "指定区域/辖区", permissions: ["behavior:view", "trajectory:view", "report:view"] },
  { key: "counselor", name: "心理辅导员(EAP)", desc: "驻场咨询师、社工", scope: "仅本人", permissions: ["behavior:view", "report:view"] },
  { key: "supervisor", name: "部门主管", desc: "班组长、部门经理，仅看本部门脱敏数据", scope: "本部门（脱敏）", permissions: ["report:view"] },
  { key: "employee", name: "员工本人", desc: "被监测员工，查看本人授权与报表", scope: "仅本人", permissions: ["consent:view", "report:view"] },
  { key: "auditor", name: "合规审计员", desc: "审计/法务/HRBP，只读全量+导出审计", scope: "园区全量", permissions: ["user:view", "role:view", "behavior:view", "trajectory:view", "report:view", "audit:view", "consent:view"] },
];
const demoAccounts: Record<string, { name: string; username: string; password: string; dept: string }> = {
  super_admin: { name: "系统管理员", username: "admin", password: "admin123", dept: "IT运维部" }, security_lead: { name: "王安全", username: "security", password: "sec123", dept: "安保部" }, guard: { name: "李巡检", username: "guard", password: "guard123", dept: "安保部" }, counselor: { name: "张心理", username: "counselor", password: "coun123", dept: "EAP心理中心" }, supervisor: { name: "赵主管", username: "supervisor", password: "sup123", dept: "生产一部" }, employee: { name: "钱员工", username: "employee", password: "emp123", dept: "生产二部" }, auditor: { name: "孙审计", username: "auditor", password: "aud123", dept: "审计法务部" },
};
const isLoggedIn = ref(false);
const authMode = ref<"login" | "register">("login");
const loginRole = ref<RoleKey>("super_admin");
const currentRole = ref<Role>(roles[0]);
const currentUser = ref(demoAccounts.super_admin);
const loginForm = ref({ username: "admin", password: "admin123" });
const registerForm = ref({ name: "", username: "", password: "", role: "employee" as RoleKey });
const authError = ref("");
const activeNav = ref("总览");
const currentPath = ref(window.location.pathname === "/" ? "/dashboard" : window.location.pathname);
const selectedRange = ref("近 7 日");
const searchText = ref("");
const showNotice = ref(false);
const modalType = ref<"alert" | "device" | "log" | "track" | "workorder" | "none">("none");
const selectedItem = ref<Record<string, string>>({});
const operationLogs = ref([
  { id: "LOG-20250618-001", account: "admin", name: "系统管理员", module: "告警中心", action: "确认真实告警", time: "2025-06-18 10:42:23", result: "成功" },
  { id: "LOG-20250618-002", account: "security", name: "王安全", module: "轨迹管理", action: "导出轨迹报表", time: "2025-06-18 10:38:11", result: "成功" },
  { id: "LOG-20250618-003", account: "guard", name: "李巡检", module: "设备管理", action: "查看设备详情", time: "2025-06-18 10:25:44", result: "成功" },
]);
const alerts = ref<AlertItem[]>([
  { id: 1, title: "人员闯入禁行区域", camera: "CAM-023", location: "南门仓储区", time: "10:42:18", level: "高", type: "区域入侵", status: "待处理" },
  { id: 2, title: "人员徘徊异常", camera: "CAM-118", location: "研发楼一层大厅", time: "10:39:52", level: "中", type: "行为异常", status: "待处理" },
  { id: 3, title: "非机动车逆行", camera: "CAM-087", location: "园区东侧路口", time: "10:35:07", level: "中", type: "交通事件", status: "待处理" },
  { id: 4, title: "消防通道占用", camera: "CAM-041", location: "生产车间 B 区", time: "10:21:43", level: "低", type: "安全生产", status: "已确认" },
]);
const chartValues = [42, 58, 48, 76, 64, 91, 72, 84, 68, 96, 77, 88];
const navItems = computed(() => {
  const all = [{ name: "总览", icon: "⌂", path: "/dashboard", permission: "" }, { name: "实时轨迹", icon: "◉", path: "/track/realtime", permission: "behavior:view" }, { name: "历史轨迹", icon: "⌁", path: "/track/history", permission: "trajectory:view" }, { name: "设备管理", icon: "▣", path: "/device/list", permission: "behavior:view" }, { name: "数据管理", icon: "▤", path: "/data/index", permission: "report:view" }, { name: "告警待办", icon: "!", path: "/alarm/todo", badge: "12", permission: "behavior:view" }, { name: "权限管理", icon: "⚙", path: "/system/index", permission: "user:view" }, { name: "操作日志", icon: "≡", path: "/data/operation-log", permission: "audit:view" }];
  return all.filter((item) => !item.permission || currentRole.value.permissions.includes(item.permission));
});
const pageTitle = computed(() => ({ "/dashboard": "总览看板", "/track/realtime": "实时轨迹管理", "/track/history": "事后轨迹查询", "/device/list": "设备列表管理", "/data/index": "数据管理", "/data/abnormal-record": "异常行为记录", "/data/track-record": "轨迹记录", "/data/backup": "数据备份与恢复", "/data/user-profile": "用户资料管理", "/data/operation-log": "系统操作日志", "/alarm/todo": "告警待办队列", "/workorder/detail/WO-20250618-001": "处置工单详情", "/system/index": "权限管理", "/system/role": "角色管理", "/system/user": "账号管理", "/403": "无权限访问" }[currentPath.value] || "总览看板"));
const filteredAlerts = computed(() => {
  const keyword = searchText.value.trim().toLowerCase();
  if (!keyword) return alerts.value;
  return alerts.value.filter((item) => `${item.title}${item.camera}${item.location}${item.type}`.toLowerCase().includes(keyword));
});
