function navigate(path: string, label?: string) { currentPath.value = path; activeNav.value = label || (navItems.value.find((item) => item.path === path)?.name || pageTitle.value); window.history.pushState({}, "", path); }
function openModal(type: typeof modalType.value, item: Record<string, string> = {}) { modalType.value = type; selectedItem.value = item; }
function closeModal() { modalType.value = "none"; selectedItem.value = {}; }
function chooseRole(key: RoleKey) { loginRole.value = key; const account = demoAccounts[key]; loginForm.value = { username: account.username, password: account.password }; }
function login() { const account = demoAccounts[loginRole.value]; if (loginForm.value.username !== account.username || loginForm.value.password !== account.password) { authError.value = "用户名或密码错误，请使用演示账号登录"; return; } currentRole.value = roles.find((role) => role.key === loginRole.value) || roles[0]; currentUser.value = account; isLoggedIn.value = true; navigate("/dashboard", "总览"); authError.value = ""; }
function register() { if (!registerForm.value.name || !registerForm.value.username || !registerForm.value.password) { authError.value = "请完整填写注册信息"; return; } currentRole.value = roles.find((role) => role.key === registerForm.value.role) || roles[5]; currentUser.value = { name: registerForm.value.name, username: registerForm.value.username, password: registerForm.value.password, dept: "待完善部门" }; isLoggedIn.value = true; authMode.value = "login"; navigate("/dashboard", "总览"); authError.value = ""; }
function logout() { isLoggedIn.value = false; authMode.value = "login"; navigate("/login", "登录"); }
function markHandled(item: AlertItem) { item.status = "已确认"; showNotice.value = true; window.setTimeout(() => (showNotice.value = false), 2200); }
window.addEventListener("popstate", () => { currentPath.value = window.location.pathname; });
