        <template v-else><h2>创建新账号</h2><p class="auth-subtitle">注册后将以指定角色进入系统</p><label>姓名</label><div class="auth-input"><span>♙</span><input v-model="registerForm.name" placeholder="请输入姓名" /></div><label>用户名</label><div class="auth-input"><span>@</span><input v-model="registerForm.username" placeholder="设置登录用户名" /></div><label>密码</label><div class="auth-input"><span>◆</span><input v-model="registerForm.password" type="password" placeholder="设置登录密码" /></div><label>注册角色</label><select v-model="registerForm.role" class="auth-select"><option v-for="role in roles.filter((item) => !['super_admin', 'security_lead', 'auditor'].includes(item.key))" :key="role.key" :value="role.key">{{ role.name }}</option></select><p v-if="authError" class="auth-error">{{ authError }}</p><button class="auth-submit" @click="register">注册并进入</button></template>
