        <template v-if="currentRole.permissions.includes('user:view') || currentRole.permissions.includes('role:view')"><p class="nav-label secondary">系统管理</p><button v-if="currentRole.permissions.includes('user:view')" class="nav-item" @click="navigate('/system/user', '账号管理')"><span class="nav-icon">♙</span><span>账号管理</span></button><button v-if="currentRole.permissions.includes('role:view')" class="nav-item" @click="navigate('/system/role', '角色管理')"><span class="nav-icon">⚙</span><span>角色管理</span></button></template>
